import { useEffect, useRef, useState } from 'react';
import { Link, useNavigate, useSearchParams } from 'react-router-dom';
import { api, ApiError, errorMessage } from '../api';
import { useSession } from '../auth';
import { Button, Field, Notice } from '../components';
import { saveDraft, usePrivateDraft } from '../offline';
import type { Page, RecordItem } from '../types';

const schemaId = 'pt-ppp-surface-v1';
const factKey = 'pt.ppp.surface_journal';
const packId = 'pt-ppp-surface-journal';
const pageSize = 16;
const keys = ['application_date_time_text', 'location_text', 'use_crop_oepp_text', 'bbch_text', 'target_text', 'treated_area_text', 'applicator_number_text', 'product_name_text', 'product_authorisation_text', 'seller_establishment_text', 'seller_activity_authorisation_text', 'quantity_or_dose_text', 'mixture_volume_text'] as const;
type CellKey = typeof keys[number];
type Raw = string | null;
type Entry = { entry_id: string; cells: Record<CellKey, Raw>; actual_date: string | null; date_confirmed: boolean };
type JournalValue = { schema_id: typeof schemaId; identity_text: Raw; observations_text: Raw; entries: Entry[] };
type SourcePin = { document_id: string; document_revision: number };
type JournalData = { farm_id: string; key: string; label: string; value: JournalValue; temporal_basis: 'static'; period: null; unit: null; sources: SourcePin[]; review_status: 'proposed' | 'confirmed' | 'rejected'; supersedes_id?: string; superseded_by?: string; notes?: string };
type Journal = RecordItem<JournalData>;
type Column = { key: CellKey; label: string; column: string; source_header: string; unit: unknown; hint: string };
type ManualSchema = { schema_id: string; fact_key: string; identity: { key: string; label: string; max_chars: number }; observations: { key: string; label: string; max_chars: number }; columns: Column[]; source: Record<string, unknown>; limits: { max_entries: number; cell_max_chars: number; block_size: number }; notice: string };
type ManualPack = { id: string; country: string; capability: string; authority_ready: boolean; manual_schema: ManualSchema };
const uuid = /^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/i;
const newValue = (): JournalValue => ({ schema_id: schemaId, identity_text: null, observations_text: null, entries: [] });
const newEntry = (): Entry => ({ entry_id: crypto.randomUUID(), cells: Object.fromEntries(keys.map(key => [key, null])) as Entry['cells'], actual_date: null, date_confirmed: false });
const today = () => { const date = new Date(); return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`; };
const copy = <T,>(value: T): T => structuredClone(value);
const jsonBytes = (value: unknown) => new TextEncoder().encode(JSON.stringify(value)).length;
const nonempty = (entry: Entry) => keys.some(key => typeof entry.cells[key] === 'string' && entry.cells[key]!.trim() !== '');
const validDate = (value: string) => /^\d{4}-\d{2}-\d{2}$/.test(value) && !Number.isNaN(Date.parse(`${value}T12:00:00Z`)) && new Date(`${value}T12:00:00Z`).toISOString().slice(0, 10) === value;

function checkedJournal(record: Journal, farm: RecordItem): Journal {
  if (!record || record.kind !== 'facts' || record.workspace_id !== farm.workspace_id || record.data?.farm_id !== farm.id || record.data.key !== factKey || !uuid.test(record.id) || !Number.isInteger(record.revision) || record.revision < 1 || record.data.value?.schema_id !== schemaId || !Array.isArray(record.data.value.entries) || record.data.value.entries.length > 256) throw new Error('This saved journal does not match this farm or its supported form. Reload it before continuing.');
  const value = record.data.value; const raw = (entry: unknown) => entry === null || typeof entry === 'string';
  if (!raw(value.identity_text) || !raw(value.observations_text) || !['proposed', 'confirmed', 'rejected'].includes(record.data.review_status)
    || record.data.temporal_basis !== 'static' || record.data.period !== null || record.data.unit !== null
    || value.entries.some((entry: Entry) => !entry || !uuid.test(entry.entry_id) || !entry.cells || Object.keys(entry.cells).length !== keys.length || keys.some(key => !raw(entry.cells[key])) || typeof entry.date_confirmed !== 'boolean' || entry.date_confirmed && entry.actual_date === null || entry.actual_date !== null && (typeof entry.actual_date !== 'string' || !validDate(entry.actual_date)))
    || new Set(value.entries.map((entry: Entry) => entry.entry_id)).size !== value.entries.length
    || !Array.isArray(record.data.sources) || record.data.sources.some((source: SourcePin) => !source || !uuid.test(source.document_id) || !Number.isInteger(source.document_revision) || source.document_revision < 1)) throw new Error('The saved journal has incomplete literal rows or source pins. Nothing has been filled in or normalised; reopen the actual saved source before continuing.');
  return record;
}

async function readJournal(id: string, farm: RecordItem, signal: AbortSignal): Promise<Journal> {
  const record = checkedJournal(await (await api.downloadResponse(`/facts/${encodeURIComponent(id)}`, { signal })).json(), farm);
  if (record.id.toLowerCase() !== id.toLowerCase()) throw new Error('The saved journal response belongs to another source. No replacement has been selected.');
  return record;
}

function checkedPack(pack: ManualPack): ManualSchema {
  const schema = pack?.manual_schema;
  if (pack?.id !== packId || pack.country !== 'PT' || pack.capability !== 'manual_preparation' || pack.authority_ready !== false || !schema || schema.schema_id !== schemaId || schema.fact_key !== factKey || !Array.isArray(schema.columns) || schema.columns.length !== keys.length || schema.columns.some((column: Column, index: number) => !column || column.key !== keys[index] || typeof column.label !== 'string' || typeof column.hint !== 'string' || column.column !== String.fromCharCode(65 + index) || column.source_header !== `${column.column}4`) || schema.limits?.max_entries !== 256 || schema.limits.block_size !== pageSize || schema.limits.cell_max_chars !== 2000 || typeof schema.identity?.label !== 'string' || typeof schema.observations?.label !== 'string' || typeof schema.notice !== 'string' || !schema.source || typeof schema.source !== 'object') throw new Error('The Portuguese form definition could not be read completely. Please retry; another country’s fields will not be substituted.');
  return schema;
}

function RawValue({ value }: { value: Raw }) {
  return value === null ? <em>Not supplied</em> : value === '' ? <em>Blank text</em> : <span style={{ whiteSpace: 'pre-wrap', overflowWrap: 'anywhere' }}>{value}{value.trim() === '' && <em> (whitespace only; {value.length} characters kept)</em>}</span>;
}

function ReadableValue({ value }: { value: unknown }) {
  if (Array.isArray(value)) return value.length ? <ul>{value.map((item, index) => <li key={index}><ReadableValue value={item}/></li>)}</ul> : null;
  if (value && typeof value === 'object') return <dl className="detail-grid">{Object.entries(value).filter(([, item]) => !Array.isArray(item) || item.length > 0).map(([key, item]) => <div key={key}><dt>{key.replaceAll('_', ' ')}</dt><dd><ReadableValue value={item}/></dd></div>)}</dl>;
  return value === undefined ? <em>Not supplied</em> : typeof value === 'boolean' ? <span>{value ? 'Yes' : 'No'}</span> : <RawValue value={value === null ? null : String(value)}/>;
}

function AnswerSources({ sources }: { sources: unknown }) {
  if (!Array.isArray(sources) || !sources.length) return null;
  return <ul>{sources.map((source: Record<string, unknown>, index) => {
    if (!source || typeof source !== 'object') return null;
    const documentId = typeof source.document_id === 'string' && uuid.test(source.document_id) ? source.document_id : null;
    let url: string | null = null;
    try { const parsed = new URL(String(source.url ?? '')); if (parsed.protocol === 'https:' && !parsed.username && !parsed.password) url = parsed.href; } catch { /* Keep unavailable references as text. */ }
    const title = String(source.title || source.source_name || source.note || 'Saved source');
    return <li key={index}>{documentId ? <Link to={`/app/documents/${documentId}`}>{title}</Link> : url ? <a href={url} target="_blank" rel="noopener noreferrer">{title}</a> : title}{source.document_revision != null && <small> · saved revision {String(source.document_revision)}</small>}</li>;
  })}</ul>;
}

function LiteralField({ label, value, onChange, max, hint }: { label: string; value: Raw; onChange: (value: Raw) => void; max: number; hint?: string }) {
  return <div className="stack"><Field label={`${label} — supplied value`}><select value={value === null ? 'unknown' : 'text'} onChange={event => onChange(event.target.value === 'unknown' ? null : '')}><option value="unknown">Not supplied</option><option value="text">Copy the source text</option></select></Field>{value !== null && <Field label={label} hint={hint}><textarea rows={2} maxLength={max} value={value} onChange={event => onChange(event.target.value)} spellCheck={false} /></Field>}</div>;
}

function Pages({ offset, total, setOffset, size = pageSize, label }: { offset: number; total: number; setOffset: (value: number) => void; size?: number; label: string }) {
  return <div className="actions" aria-label={label}><Button variant="secondary" disabled={offset === 0} onClick={() => setOffset(Math.max(0, offset - size))}>Previous page</Button><span>{total ? `${offset + 1} to ${Math.min(total, offset + size)} of ${total}` : 'No rows'}</span><Button variant="secondary" disabled={offset + size >= total} onClick={() => setOffset(offset + size)}>Next page</Button></div>;
}

function SourceDetails({ schema }: { schema: ManualSchema }) {
  const source = schema.source; let url: string | null = null;
  try { const parsed = new URL(String(source.url ?? '')); if (parsed.protocol === 'https:' && parsed.hostname && !parsed.username && !parsed.password) url = parsed.href; } catch { /* A missing source URL is not a different official route. */ }
  return <details><summary>Source form and its limits</summary><p>{String(source.title ?? 'DGAV surface-treatment model')}</p>{url && <p><a href={url} target="_blank" rel="noopener noreferrer">Read the source form (opens a new tab)</a></p>}<p>{String(source.edition ?? 'Check the retained source edition before using it.')}</p><p>The source has 16 entry spaces per sheet; the app keeps up to 256 rows in 16-row pages. Text and units stay as copied, without conversions or calculated totals.</p><p className="muted">This form does not establish product authorisation, legal applicability or recipient acceptance.</p><details><summary>Saved version details</summary><p style={{ overflowWrap: 'anywhere' }}>Source hash: {String(source.sha256 ?? source.hash ?? 'Not supplied')}</p><p>Schema: {schema.schema_id}</p></details></details>;
}

function RowTable({ value, schema, offset, setOffset, edit, move, remove, selected, onSelect, year }: { value: JournalValue; schema: ManualSchema; offset: number; setOffset: (value: number) => void; edit?: (entryId: string) => void; move?: (entryId: string, direction: number) => void; remove?: (entryId: string) => void; selected?: string[]; onSelect?: (entryId: string, checked: boolean) => void; year?: string }) {
  const start = Math.min(offset, Math.max(0, Math.floor((value.entries.length - 1) / pageSize) * pageSize));
  return <><div role="region" aria-label="Portuguese journal literal rows" tabIndex={0} style={{ overflowX: 'auto', margin: '1rem 0' }}><table><caption>Original text in source-column order. Actual dates below are separately supplied app information.</caption><thead><tr><th scope="col">Row</th>{onSelect && <th scope="col">Include</th>}<th scope="col">Separately checked actual date</th>{schema.columns.map(column => <th key={column.key} scope="col" style={{ minWidth: 150, whiteSpace: 'pre-wrap' }}>{column.column} · {column.label}</th>)}{edit && <th scope="col">Change this draft</th>}</tr></thead><tbody>{value.entries.slice(start, start + pageSize).map((entry, index) => {
    const position = start + index;
    const reason = !entry.actual_date || !entry.date_confirmed ? 'The actual date has not been separately checked.' : !validDate(entry.actual_date) ? 'The supplied actual date is not valid.' : entry.actual_date > today() ? 'The supplied actual date is in the future.' : !/^\d{4}$/.test(year || '') ? 'Choose the preview year first.' : entry.actual_date.slice(0, 4) !== year ? 'The actual date is outside the chosen preview year.' : '';
    return <tr key={entry.entry_id}><th scope="row">{position + 1}</th>{onSelect && <td><label><input type="checkbox" aria-label={`Include row ${position + 1} in the journal preview`} checked={selected?.includes(entry.entry_id) ?? false} disabled={!!reason && !selected?.includes(entry.entry_id)} onChange={event => onSelect(entry.entry_id, event.target.checked)} />Include</label>{reason && <p>{reason} The original row stays saved.</p>}</td>}<td>{entry.actual_date || 'No actual date supplied'}<br />{entry.date_confirmed ? 'Explicitly checked' : 'Not checked'}</td>{schema.columns.map(column => <td key={column.key}><RawValue value={entry.cells[column.key]} /></td>)}{edit && <td><Button variant="secondary" onClick={() => edit(entry.entry_id)}>Edit row {position + 1}</Button><Button variant="ghost" disabled={position === 0} onClick={() => move?.(entry.entry_id, -1)}>Move row {position + 1} earlier</Button><Button variant="ghost" disabled={position === value.entries.length - 1} onClick={() => move?.(entry.entry_id, 1)}>Move row {position + 1} later</Button><Button variant="ghost" onClick={() => remove?.(entry.entry_id)}>Remove row {position + 1}</Button></td>}</tr>;
  })}</tbody></table></div>{!value.entries.length && <p>No rows have been added. You can save the producer or observations as a partial draft.</p>}<Pages offset={start} total={value.entries.length} setOffset={setOffset} label="Journal row pages" /></>;
}

function DocumentSources({ farm, choices, onChange }: { farm: RecordItem; choices: SourcePin[]; onChange?: (value: SourcePin[]) => void }) {
  const [offset, setOffset] = useState(0); const [refresh, setRefresh] = useState(0);
  const [result, setResult] = useState<{ key: string; page?: Page; error?: string }>({ key: '' });
  const key = `${farm.id}/${farm.revision}/${offset}/${refresh}`; const current = result.key === key ? result : null;
  useEffect(() => {
    if (!onChange) return;
    const controller = new AbortController(); let active = true;
    api.downloadResponse(`/documents?${new URLSearchParams({ farm_id: farm.id, limit: '10', offset: String(offset) })}`, { signal: controller.signal }).then(response => response.json() as Promise<Page>).then(page => { if (!Array.isArray(page.items) || page.items.some(document => document.workspace_id !== farm.workspace_id || document.data.farm_id !== farm.id)) throw new Error('These source documents do not match this farm.'); if (active) setResult({ key, page }); }).catch(reason => { if (active && !controller.signal.aborted) setResult({ key, error: errorMessage(reason) }); });
    return () => { active = false; controller.abort(); };
  }, [key, !!onChange]);
  return <details><summary>Original documents used to copy these rows (optional)</summary><p>Choose only actual documents from this farm. Typing a row is not documentary evidence. A selected document keeps its exact saved revision.</p>{choices.length ? <ul>{choices.map(pin => <li key={pin.document_id}><Link to={`/app/documents/${pin.document_id}`}>Open selected original</Link>{onChange && <Button variant="ghost" onClick={() => onChange(choices.filter(value => value.document_id !== pin.document_id))}>Remove source</Button>}<details><summary>Saved version details</summary><p>{pin.document_id} · revision {pin.document_revision}</p></details></li>)}</ul> : <p>No original document is selected. No source will be invented.</p>}{onChange && <>{current?.error ? <Notice kind="error">{current.error}<Button variant="secondary" onClick={() => setRefresh(value => value + 1)}>Retry original documents</Button></Notice> : !current?.page ? <p role="status">Opening this farm’s original documents…</p> : <>{current.page.items.map(document => { const chosen = choices.find(pin => pin.document_id === document.id); return <div key={document.id}><label className="check-row"><input type="checkbox" checked={!!chosen} disabled={!chosen && choices.length >= 100} onChange={event => onChange(event.target.checked ? [...choices, { document_id: document.id, document_revision: document.revision }] : choices.filter(pin => pin.document_id !== document.id))} />{String(document.data.title || document.data.filename || 'Saved original')}</label>{chosen && chosen.document_revision !== document.revision && <Notice kind="warning">This source changed. Open it before choosing the new revision.<Button variant="secondary" onClick={() => onChange(choices.map(pin => pin.document_id === document.id ? { document_id: document.id, document_revision: document.revision } : pin))}>I checked the current original; use this version</Button></Notice>}</div>; })}<Pages offset={offset} total={current.page.total} size={10} setOffset={setOffset} label="Original document pages" /></>}<Button variant="secondary" onClick={() => setRefresh(value => value + 1)}>Refresh original documents</Button><p><Link to={`/app/documents?farm_id=${farm.id}`}>Add an actual document</Link></p></>}</details>;
}

type EditorDraft = { attempt: string; baseRevision: number; value: JournalValue; sources: SourcePin[]; notes: string };
function JournalEditor({ farm, schema, record, correction, scope, onSaved, onClose }: { farm: RecordItem; schema: ManualSchema; record?: Journal; correction: boolean; scope: string; onSaved: (value: Journal) => void; onClose: () => void }) {
  const initial = useRef<EditorDraft>({ attempt: crypto.randomUUID(), baseRevision: record?.revision ?? 0, value: record ? copy(record.data.value) : newValue(), sources: record ? copy(record.data.sources || []) : [], notes: record?.data.notes ?? '' });
  const draftName = `pt-journal/${farm.id}/${record?.id || 'new'}/${correction ? 'correction' : 'draft'}`;
  const draft = usePrivateDraft<EditorDraft>(draftName, initial.current); const value = draft.value;
  const [offset, setOffset] = useState(0); const [editing, setEditing] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [latest, setLatest] = useState<Journal | null>(null); const [acceptedLatest, setAcceptedLatest] = useState<Journal | null>(null); const [compared, setCompared] = useState(false);
  const mounted = useRef(true); const request = useRef<AbortController | null>(null); const current = useRef(value); current.current = value;
  useEffect(() => { mounted.current = true; return () => { mounted.current = false; request.current?.abort(); }; }, []);
  const baseline = acceptedLatest && (!record || acceptedLatest.revision > record.revision) ? acceptedLatest : record;
  const stale = !!baseline && baseline.revision !== value.baseRevision || !!latest;
  const editingRow = value.value.entries.find(entry => entry.entry_id === editing);
  function change(update: (previous: EditorDraft) => EditorDraft) { if (busy) return; draft.setValue(previous => ({ ...update(previous), attempt: crypto.randomUUID() })); setError(''); }
  function rowChange(update: (previous: Entry) => Entry) { change(previous => ({ ...previous, value: { ...previous.value, entries: previous.value.entries.map(entry => entry.entry_id === editing ? update(entry) : entry) } })); }
  async function save() {
    if (!draft.ready || busy || stale) return; setBusy(true); setError(''); const captured = value; const controller = new AbortController(); request.current = controller;
    try {
      if (captured.value.entries.some(entry => !nonempty(entry))) throw new Error('A row has no supplied cell. Enter at least one original value or explicitly remove that row. Empty rows will not be silently dropped.');
      const data = { farm_id: farm.id, key: factKey, ...(record && !correction ? {} : { label: record?.data.label ?? 'Portuguese surface-treatment journal' }), value: captured.value, sources: captured.sources, temporal_basis: 'static', period: null, unit: null, review_status: 'proposed', notes: captured.notes, ...(correction && record ? { supersedes_id: record.id } : {}) };
      if (jsonBytes({ data }) > 512000) throw new Error('This journal exceeds the app’s 512,000-byte draft limit. Keep the text here and split it into smaller journals; no value has been shortened.');
      await saveDraft(scope, draftName, captured);
      if (record) { const fresh = await readJournal(record.id, farm, controller.signal); if (fresh.revision !== captured.baseRevision || correction && fresh.data.review_status !== 'confirmed' || !correction && fresh.data.review_status !== 'proposed') { if (mounted.current) { setLatest(fresh); setCompared(false); } throw new Error('The saved source changed. Compare every saved row and source before keeping or replacing your private entries.'); } }
      if (!mounted.current || controller.signal.aborted) return;
      const saved = checkedJournal(record && !correction ? await api.patch<Journal>(`/facts/${record.id}`, { expected_revision: captured.baseRevision, data }) : await api.post<Journal>('/facts', { data }, { idempotencyKey: captured.attempt, signal: controller.signal }), farm);
      if (!mounted.current || controller.signal.aborted || current.current.attempt !== captured.attempt) return;
      await draft.clear(); if (mounted.current) onSaved(saved);
    } catch (reason) { if (mounted.current && !controller.signal.aborted) { setError(errorMessage(reason)); if (reason instanceof ApiError && reason.status === 409 && record) { try { const fresh = await readJournal(record.id, farm, controller.signal); if (mounted.current) { setLatest(fresh); setCompared(false); } } catch { /* Keep the stale error and private entries; never rebase on a failed read. */ } } } }
    finally { if (mounted.current) setBusy(false); }
  }
  const comparison = latest || baseline;
  function keepCompared() { if (!comparison || !compared) return; draft.setValue(previous => ({ ...previous, baseRevision: comparison.revision, attempt: crypto.randomUUID() })); setAcceptedLatest(comparison); setLatest(null); setCompared(false); }
  return <section className="card"><h3>{correction ? 'Prepare a correction to the checked journal' : record ? 'Edit the proposed journal' : 'Start a Portuguese surface-treatment journal'}</h3><p>Copy exactly what is supplied. Unknown, empty text, zero and explicit “not applicable” text are different. No date, unit, identifier or total is inferred.</p>{!draft.ready && <p role="status">Opening your protected journal draft…</p>}{draft.saving && <p role="status">Saving the private draft on this device…</p>}{draft.error && <Notice kind="warning">{draft.error} Keep this page open until the journal is saved.</Notice>}{error && <Notice kind="error">{error} Your private entries have been kept.</Notice>}
    {stale && comparison && <Notice kind="warning"><p>The saved journal changed after this private draft began. Compare its producer, observations, every row, notes and original source before choosing what to keep.</p><h4>Latest saved producer</h4><RawValue value={comparison.data.value.identity_text} /><h4>Latest saved global observations</h4><RawValue value={comparison.data.value.observations_text} /><h4>Latest saved draft notes</h4><RawValue value={comparison.data.notes ?? null} /><RowTable value={comparison.data.value} schema={schema} offset={offset} setOffset={setOffset} /><DocumentSources farm={farm} choices={comparison.data.sources || []} /><label className="check-row"><input type="checkbox" checked={compared} onChange={event => setCompared(event.target.checked)} />I compared all saved rows and sources with my private entries.</label><Button variant="secondary" disabled={!compared || comparison.data.review_status !== (correction ? 'confirmed' : 'proposed')} onClick={keepCompared}>Keep my entries after comparing this saved version</Button></Notice>}
    <fieldset className="draft-fields" disabled={!draft.ready || busy}>
      <LiteralField label={schema.identity.label} value={value.value.identity_text} max={1000} onChange={identity_text => change(previous => ({ ...previous, value: { ...previous.value, identity_text } }))} />
      <LiteralField label={`${schema.observations.label} — whole journal`} value={value.value.observations_text} max={8000} hint="These observations describe the whole prepared document, not each application." onChange={observations_text => change(previous => ({ ...previous, value: { ...previous.value, observations_text } }))} />
      <p>{value.value.entries.length} of 256 app rows. Row order is retained; rows are not sorted or combined.</p>
      <RowTable value={value.value} schema={schema} offset={offset} setOffset={setOffset} edit={setEditing} move={(entryId, direction) => change(previous => { const entries = [...previous.value.entries]; const index = entries.findIndex(entry => entry.entry_id === entryId); const target = index + direction; if (target >= 0 && target < entries.length) [entries[index], entries[target]] = [entries[target], entries[index]]; return { ...previous, value: { ...previous.value, entries } }; })} remove={entryId => { change(previous => ({ ...previous, value: { ...previous.value, entries: previous.value.entries.filter(entry => entry.entry_id !== entryId) } })); if (editing === entryId) setEditing(''); setOffset(0); }} />
      <Button variant="secondary" disabled={value.value.entries.length >= 256} onClick={() => { const entry = newEntry(); change(previous => ({ ...previous, value: { ...previous.value, entries: [...previous.value.entries, entry] } })); setEditing(entry.entry_id); setOffset(Math.floor(value.value.entries.length / pageSize) * pageSize); }}>Add a journal row</Button>
      {editingRow && <section className="paper-section"><h4>Edit row {value.value.entries.findIndex(entry => entry.entry_id === editing) + 1}</h4><p>Columns H–M concern the product and selling establishment. The producer’s identity belongs at the top, not in the product-name column.</p>{schema.columns.map(column => <LiteralField key={column.key} label={`${column.column} · ${column.label}`} hint={column.hint} max={2000} value={editingRow.cells[column.key]} onChange={raw => rowChange(previous => ({ ...previous, cells: { ...previous.cells, [column.key]: raw }, ...(column.key === 'application_date_time_text' ? { date_confirmed: false } : {}) }))} />)}<Field label="Actual application date, supplied separately" hint="Choose only a date you checked yourself. Column A stays exactly as typed; it is never parsed to fill this date."><input type="date" value={editingRow.actual_date ?? ''} onChange={event => rowChange(previous => ({ ...previous, actual_date: event.target.value || null, date_confirmed: false }))} /></Field><label className="check-row"><input type="checkbox" checked={editingRow.date_confirmed} disabled={!editingRow.actual_date || !validDate(editingRow.actual_date)} onChange={event => rowChange(previous => ({ ...previous, date_confirmed: event.target.checked }))} />I checked the actual application date separately from column A.</label><Button variant="secondary" onClick={() => setEditing('')}>Close row editor</Button></section>}
      <DocumentSources farm={farm} choices={value.sources} onChange={sources => change(previous => ({ ...previous, sources }))} />
      <Field label="Notes about this draft or correction"><textarea maxLength={4000} value={value.notes} onChange={event => change(previous => ({ ...previous, notes: event.target.value }))} /></Field>
      <div className="actions"><Button loading={busy} disabled={stale} onClick={() => void save()}>Save proposed Portuguese journal</Button><Button variant="secondary" onClick={onClose}>Close and keep my private draft</Button></div>
      <p>Saving allows incomplete or undated rows. It does not confirm the journal or create a dated work, purchase or water record.</p>
    </fieldset>
  </section>;
}

function JournalReview({ farm, record, onSaved }: { farm: RecordItem; record: Journal; onSaved: (value: Journal) => void }) {
  const [note, setNote] = useState(''); const [ack, setAck] = useState(false); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const mounted = useRef(true); const request = useRef<AbortController | null>(null);
  const retry = useRef<{ body: string; key: string } | null>(null);
  useEffect(() => { mounted.current = true; return () => { mounted.current = false; request.current?.abort(); }; }, []);
  async function review(decision: 'confirmed' | 'rejected') {
    if (!ack || !note.trim() || busy) return; setBusy(true); setError(''); const controller = new AbortController(); request.current = controller;
    try { const body = { expected_revision: record.revision, decision, note }; const serialized = JSON.stringify(body); const attempt = retry.current?.body === serialized ? retry.current : { body: serialized, key: crypto.randomUUID() }; retry.current = attempt; const saved = checkedJournal(await api.post<Journal>(`/facts/${record.id}/review`, body, { idempotencyKey: attempt.key, signal: controller.signal }), farm); if (saved.id !== record.id) throw new Error('The returned review belongs to another journal. Reload this source.'); if (mounted.current && !controller.signal.aborted) onSaved(saved); }
    catch (reason) { if (mounted.current && !controller.signal.aborted) { setError(errorMessage(reason)); setAck(false); } } finally { if (mounted.current) setBusy(false); }
  }
  return <section className="card"><h4>Check this saved journal separately</h4><p>Compare the producer, global observations, all pages of raw rows and source documents above. Confirmation records your review, not legal completeness. Missing dates can remain known gaps until you prepare a year-specific selection.</p>{record.data.supersedes_id && <Notice>This is a proposed correction. Confirming it retires the previous checked journal while keeping its history and earlier report snapshots.</Notice>}{error && <Notice kind="error">{error}<p>Reload the saved journal before reviewing a changed source.</p></Notice>}<Field label="What did you compare before checking this journal?"><textarea value={note} maxLength={4000} onChange={event => { setNote(event.target.value); setAck(false); }} /></Field><label className="check-row"><input type="checkbox" checked={ack} onChange={event => setAck(event.target.checked)} />I compared every saved page and the original records. This confirms only my review of these literal entries.</label><div className="actions"><Button loading={busy} disabled={!ack || !note.trim()} onClick={() => void review('confirmed')}>Confirm this Portuguese journal</Button><Button variant="secondary" loading={busy} disabled={!ack || !note.trim()} onClick={() => void review('rejected')}>Reject this proposed journal</Button></div></section>;
}

type PreparationContext = { report?: RecordItem; request?: RecordItem };
type ReportPin = { id: string; revision: number; title: string };
type PinProof = { key: string; valid: boolean };
type SelectionDraft = { attempt: string; sourceRevision: number; year: string; ids: string[]; documentIds: string[]; extraFacts?: ReportPin[]; documentPins?: ReportPin[]; reportId: string; originalReportRevision: number; originalReportChecksum: string; requestRevision: number };
const pinKey = (pins: ReportPin[]) => JSON.stringify(pins.map(pin => [pin.id, pin.revision]));
const eligibleExtraFact = (record: RecordItem) => record.data.review_status === 'confirmed' && !record.data.superseded_by && record.data.key !== factKey && record.data.value?.schema_id !== schemaId;
function checkedReportSource(record: RecordItem, kind: 'facts' | 'documents', farm: RecordItem): RecordItem {
  if (!record || record.kind !== kind || record.workspace_id !== farm.workspace_id || record.data?.farm_id !== farm.id || !uuid.test(record.id) || !Number.isSafeInteger(record.revision) || record.revision < 1) throw new Error('This saved record does not match this farm. No replacement has been selected.');
  return record;
}
async function checkReportPins(pins: ReportPin[], kind: 'facts' | 'documents', farm: RecordItem, signal: AbortSignal) {
  if (new Set(pins.map(pin => pin.id)).size !== pins.length) throw new Error('A report record was selected more than once. Remove the duplicate and choose it again.');
  for (const pin of pins) {
    if (!uuid.test(pin.id) || !Number.isSafeInteger(pin.revision) || pin.revision < 1) throw new Error(`${pin.title}: this earlier choice has no saved version. Remove it and explicitly choose the current record below.`);
    try {
      const fresh = checkedReportSource(await (await api.downloadResponse(`/${kind}/${pin.id}`, { signal })).json(), kind, farm);
      if (fresh.id !== pin.id || fresh.revision !== pin.revision || kind === 'facts' && !eligibleExtraFact(fresh)) throw new Error('The saved version changed or this answer is no longer a current confirmed answer. Remove the choice, read the current record and choose it again.');
    } catch (reason) { if (signal.aborted) throw reason; throw new Error(`${pin.title}: ${errorMessage(reason)} No different record or version has been substituted.`); }
  }
}

function ReportSources({ farm, kind, choices, onChange, onProof }: { farm: RecordItem; kind: 'facts' | 'documents'; choices: ReportPin[]; onChange: (pins: ReportPin[]) => void; onProof: (proof: PinProof) => void }) {
  const [opened, setOpened] = useState(false); const [offset, setOffset] = useState(0); const [selectedOffset, setSelectedOffset] = useState(0); const [refresh, setRefresh] = useState(0);
  const [result, setResult] = useState<{ key: string; page?: Page; error?: string }>({ key: '' });
  const [verification, setVerification] = useState<{ key: string; error?: string; checked?: boolean }>({ key: '' });
  const size = kind === 'facts' ? 5 : 10; const selectedKey = pinKey(choices); const key = `${farm.id}/${farm.revision}/${kind}/${offset}/${refresh}`;
  const current = result.key === key ? result : null; const verified = verification.key === `${selectedKey}/${refresh}` ? verification : null;
  useEffect(() => {
    if (!opened) return;
    const controller = new AbortController(); let active = true;
    api.downloadResponse(`/${kind}?${new URLSearchParams({ farm_id: farm.id, limit: String(size), offset: String(offset) })}`, { signal: controller.signal }).then(response => response.json() as Promise<Page>).then(page => {
      if (!Array.isArray(page.items) || !Number.isSafeInteger(page.total) || page.total < 0 || page.limit !== size || page.offset !== offset || page.items.length > size) throw new Error('This page of saved records is incomplete. Retry before choosing a record.');
      page.items.forEach(item => checkedReportSource(item, kind, farm)); if (active) setResult({ key, page });
    }).catch(reason => { if (active && !controller.signal.aborted) setResult({ key, error: errorMessage(reason) }); });
    return () => { active = false; controller.abort(); };
  }, [opened, key]);
  useEffect(() => {
    const controller = new AbortController(); let active = true; const proofKey = `${selectedKey}/${refresh}`;
    onProof({ key: selectedKey, valid: choices.length === 0 }); setVerification({ key: proofKey, checked: choices.length === 0 });
    if (choices.length) void checkReportPins(choices, kind, farm, controller.signal).then(() => { if (active) { setVerification({ key: proofKey, checked: true }); onProof({ key: selectedKey, valid: true }); } }).catch(reason => { if (active && !controller.signal.aborted) { setVerification({ key: proofKey, error: errorMessage(reason) }); onProof({ key: selectedKey, valid: false }); } });
    return () => { active = false; controller.abort(); };
  }, [selectedKey, refresh, onProof]);
  const visible = current?.page?.items.filter(item => kind !== 'facts' || eligibleExtraFact(item)) ?? [];
  const selectedStart = Math.min(selectedOffset, Math.max(0, Math.floor((choices.length - 1) / pageSize) * pageSize));
  function choose(pins: ReportPin[]) { onProof({ key: pinKey(pins), valid: pins.length === 0 }); onChange(pins); }
  function refreshSources() { onProof({ key: selectedKey, valid: choices.length === 0 }); setRefresh(value => value + 1); }
  return <details onToggle={event => setOpened(event.currentTarget.open)}><summary>{kind === 'facts' ? 'Other checked answers for this letter or report (optional)' : 'Original files to include in the report (optional)'}</summary>
    <p>{kind === 'facts' ? 'Choose other confirmed answers from this farm only when the letter needs them. Other Portuguese journals are not offered. The report will still check missing answers and conflicting sources.' : 'Choose actual documents from this farm. These are report attachments, separate from the private source documents used to check the journal. No original file is included automatically.'}</p>
    <p>{choices.length} {kind === 'facts' ? 'other answers' : 'original files'} selected.</p>
    {!!choices.length && <><ul>{choices.slice(selectedStart, selectedStart + pageSize).map(pin => <li key={pin.id}>{pin.title}{kind === 'documents' && <>{' '}<Link to={`/app/documents/${pin.id}`}>Read selected original</Link></>}<Button variant="ghost" onClick={() => choose(choices.filter(item => item.id !== pin.id))}>Remove {kind === 'facts' ? 'answer' : 'attachment'}: {pin.title}</Button><details><summary>Saved version details</summary><p>{pin.id} · revision {pin.revision || 'not bound; choose again'}</p></details></li>)}</ul><Pages offset={selectedStart} total={choices.length} size={pageSize} setOffset={setSelectedOffset} label={`Selected ${kind} pages`} />{verified?.error ? <Notice kind="error">{verified.error}<p>Remove the affected choice before reading and choosing its current version. Your private selection is retained.</p></Notice> : !verified?.checked ? <p role="status">Checking access and the saved versions of selected records…</p> : <p>The selected saved versions are available. They will be checked again before preparation.</p>}</>}
    {opened && (current?.error ? <Notice kind="error">{current.error}<Button variant="secondary" onClick={() => setRefresh(value => value + 1)}>Retry {kind === 'facts' ? 'other checked answers' : 'report attachments'}</Button></Notice> : !current?.page ? <p role="status">Opening this farm’s {kind === 'facts' ? 'saved answers' : 'documents'}…</p> : <>{visible.length ? visible.map(item => { const selected = choices.find(pin => pin.id === item.id); const title = String(item.data.label || item.data.title || item.data.filename || (kind === 'facts' ? 'Saved answer' : 'Saved original')); return <div className="card" key={item.id}><label className="check-row"><input type="checkbox" checked={!!selected} disabled={!selected && choices.length >= (kind === 'facts' ? 4999 : 250)} onChange={event => choose(event.target.checked ? [...choices, { id: item.id, revision: item.revision, title }] : choices.filter(pin => pin.id !== item.id))} />{title}</label>{kind === 'facts' ? <><dl className="detail-grid">{Object.entries({ Value: item.data.value, Unit: item.data.unit, Period: item.data.period, 'Time basis': item.data.temporal_basis }).filter(([, value]) => !Array.isArray(value) || value.length > 0).map(([label, value]) => <div key={label}><dt>{label}</dt><dd><ReadableValue value={value}/></dd></div>)}</dl><AnswerSources sources={item.data.sources}/></> : <p><Link to={`/app/documents/${item.id}`}>Read this original document</Link></p>}{selected && selected.revision !== item.revision && <Notice kind="warning">This record changed. Remove the old choice, read this current record and explicitly select it again.</Notice>}</div>; }) : <p>{kind === 'facts' ? 'No checked answers are available on this page.' : 'No documents are available on this page.'}</p>}<Pages offset={offset} total={current.page.total} size={size} setOffset={setOffset} label={`${kind === 'facts' ? 'Farm answer' : 'Report attachment'} pages`} />{kind === 'facts' && <p className="muted">Only current confirmed non-journal answers can be selected.</p>}</>)}
    {opened && !current?.page && offset > 0 && <Button variant="secondary" onClick={() => setOffset(Math.max(0, offset - size))}>Previous page</Button>}
    <Button variant="secondary" onClick={refreshSources}>Refresh {kind === 'facts' ? 'other checked answers' : 'report attachments'}</Button>{kind === 'documents' && <p><Link to={`/app/documents?farm_id=${farm.id}`}>Add an actual document</Link></p>}
  </details>;
}

function PrepareJournal({ farm, record, schema, scope, context }: { farm: RecordItem; record: Journal; schema: ManualSchema; scope: string; context: PreparationContext }) {
  const navigate = useNavigate(); const name = `pt-journal/${farm.id}/${record.id}/selection/${context.report?.id || context.request?.id || 'unlinked'}`;
  const contextPins = { originalReportRevision: context.report?.revision ?? 0, originalReportChecksum: String(context.report?.data.checksum ?? ''), requestRevision: context.request?.revision ?? 0 };
  const fixedYear = context.report?.data.reporting_year ?? context.request?.data.reporting_year;
  const draft = usePrivateDraft<SelectionDraft>(name, { attempt: crypto.randomUUID(), sourceRevision: record.revision, year: '', ids: [], documentIds: [], extraFacts: [], documentPins: [], reportId: '', ...contextPins });
  const value = draft.value; const [ack, setAck] = useState(false); const [offset, setOffset] = useState(0); const [selectedOffset, setSelectedOffset] = useState(0); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const mounted = useRef(true); const request = useRef<AbortController | null>(null);
  const extraFacts = value.extraFacts ?? []; const documentPins = value.documentPins ?? value.documentIds.map(id => ({ id, revision: 0, title: 'Previously selected original' }));
  const [factProof, setFactProof] = useState<PinProof>({ key: '', valid: false }); const [documentProof, setDocumentProof] = useState<PinProof>({ key: '', valid: false });
  const pinsReady = (!extraFacts.length || factProof.key === pinKey(extraFacts) && factProof.valid) && (!documentPins.length || documentProof.key === pinKey(documentPins) && documentProof.valid);
  useEffect(() => { if (!pinsReady) setAck(false); }, [pinsReady]);
  useEffect(() => { mounted.current = true; return () => { mounted.current = false; request.current?.abort(); }; }, []);
  const stale = value.sourceRevision !== record.revision || value.originalReportRevision !== contextPins.originalReportRevision || value.originalReportChecksum !== contextPins.originalReportChecksum || value.requestRevision !== contextPins.requestRevision;
  const problem = (entry?: Entry) => !entry ? 'The selected row is no longer in this source.' : !entry.actual_date || !entry.date_confirmed ? 'An actual date has not been separately checked.' : !validDate(entry.actual_date) || entry.actual_date > today() ? 'The actual date is invalid or in the future.' : entry.actual_date.slice(0, 4) !== value.year ? 'The actual date does not match the chosen preview year.' : '';
  const invalid = value.ids.filter(id => problem(record.data.value.entries.find(entry => entry.entry_id === id)));
  function edit(update: (previous: SelectionDraft) => SelectionDraft) { draft.setValue(previous => ({ ...update(previous), attempt: crypto.randomUUID(), reportId: '' })); setAck(false); setError(''); }
  async function prepare() {
    if (!draft.ready || !ack || busy || stale || !pinsReady || !value.ids.length || invalid.length) return; setBusy(true); setError(''); const controller = new AbortController(); request.current = controller;
    try {
      if (!/^\d{4}$/.test(value.year) || Number(value.year) < 2000 || Number(value.year) > 2200) throw new Error('Choose the year for this app preview. It is not a year printed by the source form.');
      if (fixedYear !== undefined && Number(value.year) !== fixedYear) throw new Error(`This ${context.report ? 'correction keeps the original report' : 'linked request is for'} year ${fixedYear}. Select rows from that year. Start a separate unlinked preview for another year.`);
      if (!record.data.value.identity_text?.trim()) throw new Error('The producer identity is still missing. Prepare a correction and check it before creating this preview.');
      await saveDraft(scope, name, value); if (!mounted.current || controller.signal.aborted) return;
      await checkReportPins(extraFacts, 'facts', farm, controller.signal); await checkReportPins(documentPins, 'documents', farm, controller.signal); if (!mounted.current || controller.signal.aborted) return;
      const selection = { fact_ids: [record.id, ...extraFacts.map(pin => pin.id)], operation_ids: [], selected_document_ids: documentPins.map(pin => pin.id), manual_journal_selection: { source_fact_id: record.id, source_fact_revision: value.sourceRevision, entry_ids: value.ids, acknowledged_unresolved: true } };
      const body = context.report ? { ...selection, expected_revision: value.originalReportRevision, snapshot_checksum: value.originalReportChecksum } : { ...selection, farm_id: farm.id, request_id: context.request?.id ?? null, pack_id: packId, reporting_year: Number(value.year) };
      const saved = await api.post<RecordItem>(context.report ? `/reports/${context.report.id}/reissue` : '/reports', body, { idempotencyKey: value.attempt, signal: controller.signal });
      const expectedRequest = context.report ? context.report.data.request_id ?? null : context.request?.id ?? null;
      if (!mounted.current || controller.signal.aborted) return; if (saved.workspace_id !== farm.workspace_id || saved.data.farm_id !== farm.id || saved.data.pack_id !== packId || saved.data.status !== 'draft' || saved.data.request_id !== expectedRequest || context.report && saved.data.correction_of !== context.report.id) throw new Error('The preview response does not match this farm and source. Reopen your saved reports before trying again.');
      draft.setValue(previous => ({ ...previous, reportId: saved.id })); navigate(`/app/reports/${saved.id}`);
    } catch (reason) { if (mounted.current && !controller.signal.aborted) { setError(errorMessage(reason)); setAck(false); } } finally { if (mounted.current) setBusy(false); }
  }
  return <section className="card"><h4>{context.report ? 'Choose replacement rows for a corrected journal preview' : 'Choose rows for a journal preview'}</h4><p>The app preview year is selection information, not a field from the DGAV workbook. Only rows with separately checked actual dates in that year can be included. Undated and other-year rows stay in the saved source.</p>{!draft.ready && <p role="status">Opening your private row selection…</p>}{draft.saving && <p role="status">Saving the private selection…</p>}{draft.error && <Notice kind="warning">{draft.error}</Notice>}{error && <Notice kind="error">{error}</Notice>}{value.reportId && <p><Link to={`/app/reports/${value.reportId}`}>Open the saved journal preview</Link></p>}{stale && <Notice kind="warning">The selected journal, request or original report version changed. Your row choices have not been silently updated. Compare the saved context and all rows before starting a new selection.<Button variant="secondary" onClick={() => { edit(previous => ({ ...previous, sourceRevision: record.revision, ...contextPins, ids: [], documentIds: [], extraFacts: [], documentPins: [] })); setSelectedOffset(0); }}>I checked this journal; start a new explicit selection</Button></Notice>}
    <fieldset className="draft-fields" disabled={!draft.ready || busy || stale}><Field label="Year for this app journal preview" hint={fixedYear !== undefined ? `This ${context.report ? 'correction retains the original report' : 'actual request is for'} year ${fixedYear}. Enter that year; a different year needs a separate new preview.` : undefined}><input type="number" min="2000" max="2200" value={value.year} onChange={event => edit(previous => ({ ...previous, year: event.target.value }))} /></Field>{fixedYear !== undefined && value.year && Number(value.year) !== fixedYear && <Notice kind="warning">Choose {fixedYear} to match the linked request or original report. Nothing will be silently moved to another year.</Notice>}<RowTable value={record.data.value} schema={schema} offset={offset} setOffset={setOffset} selected={value.ids} onSelect={(id, checked) => edit(previous => ({ ...previous, ids: checked ? [...previous.ids, id] : previous.ids.filter(value => value !== id) }))} year={value.year} />
      <h4>Selected row order</h4><p>{value.ids.length} rows selected. Selection order is retained; it is not inferred from dates.</p><ol start={selectedOffset + 1}>{value.ids.slice(selectedOffset, selectedOffset + pageSize).map((id, index) => { const position = selectedOffset + index; const row = record.data.value.entries.find(entry => entry.entry_id === id); return <li key={id}>Source row {record.data.value.entries.findIndex(entry => entry.entry_id === id) + 1} · {row?.actual_date || 'Date not supplied'}{problem(row) && <p>{problem(row)} Remove this selection or correct the source.</p>}<div className="actions"><Button variant="ghost" disabled={position === 0} onClick={() => edit(previous => { const ids = [...previous.ids]; [ids[position - 1], ids[position]] = [ids[position], ids[position - 1]]; return { ...previous, ids }; })}>Move selection {position + 1} earlier</Button><Button variant="ghost" disabled={position === value.ids.length - 1} onClick={() => edit(previous => { const ids = [...previous.ids]; [ids[position], ids[position + 1]] = [ids[position + 1], ids[position]]; return { ...previous, ids }; })}>Move selection {position + 1} later</Button><Button variant="ghost" onClick={() => { edit(previous => ({ ...previous, ids: previous.ids.filter(value => value !== id) })); setSelectedOffset(0); }}>Remove selection {position + 1}</Button></div></li>; })}</ol><Pages offset={selectedOffset} total={value.ids.length} setOffset={setSelectedOffset} label="Selected row order pages" />
      <p>{record.data.value.entries.filter(entry => !value.ids.includes(entry.entry_id)).length} source rows are not selected. Their original text is kept; excluded rows and reasons will remain visible in the report.</p>{!!invalid.length && <Notice kind="warning">{invalid.length} selected rows cannot be included for this year. No row or raw date text has been rewritten.</Notice>}
      <ReportSources farm={farm} kind="facts" choices={extraFacts} onChange={pins => edit(previous => ({ ...previous, extraFacts: pins }))} onProof={setFactProof} />
      <ReportSources farm={farm} kind="documents" choices={documentPins} onChange={pins => edit(previous => ({ ...previous, documentPins: pins, documentIds: pins.map(pin => pin.id) }))} onProof={setDocumentProof} />
      {!pinsReady && <Notice kind="warning">The selected extra answers or attachments still need their saved versions checked. Open their choices above to review any error; no changed or inaccessible version will be silently substituted.</Notice>}
      <label className="check-row"><input type="checkbox" checked={ack} disabled={!pinsReady} onChange={event => setAck(event.target.checked)} />I checked the selected rows, their order and actual dates. I understand that unknown or empty cells still need checking and this preview does not send anything.</label><Button loading={busy} disabled={!ack || !pinsReady || !value.ids.length || !!invalid.length || !value.year || fixedYear !== undefined && Number(value.year) !== fixedYear} onClick={() => void prepare()}>{context.report ? 'Prepare corrected Portuguese rows' : 'Prepare selected Portuguese rows'}</Button><p>This creates a draft report for separate review and approval. It does not send the journal or prove national completeness.</p>
    </fieldset>
  </section>;
}

function FarmJournal({ farm, scope, canReview }: { farm: RecordItem; scope: string; canReview: boolean }) {
  const [params] = useSearchParams(); const linkedFact = params.get('pt_journal_fact'); const linkedRevision = params.get('pt_journal_fact_revision');
  const reissueId = params.get('pt_journal_reissue'); const requestId = params.get('pt_journal_request'); const contextRequested = reissueId !== null || requestId !== null;
  const [contextRefresh, setContextRefresh] = useState(0); const [contextState, setContextState] = useState<{ key: string; value?: PreparationContext; error?: string }>({ key: '' });
  const contextKey = JSON.stringify([params.getAll('pt_journal_reissue'), params.getAll('pt_journal_request'), contextRefresh]);
  const preparation: PreparationContext | null = !contextRequested ? {} : contextState.key === contextKey ? contextState.value ?? null : null;
  const contextError = contextState.key === contextKey ? contextState.error : null;
  const [linkError, setLinkError] = useState(''); const [linkNotice, setLinkNotice] = useState('');
  const [schema, setSchema] = useState<ManualSchema | null>(null); const [schemaError, setSchemaError] = useState(''); const [schemaRefresh, setSchemaRefresh] = useState(0);
  const [offset, setOffset] = useState(0); const [refresh, setRefresh] = useState(0); const [result, setResult] = useState<{ key: string; page?: Page<Journal>; error?: string }>({ key: '' });
  const [target, setTarget] = useState(''); const [record, setRecord] = useState<Journal | null>(null); const [recordError, setRecordError] = useState(''); const [recordLoading, setRecordLoading] = useState(false); const [editor, setEditor] = useState<'new' | 'edit' | 'correct' | ''>(''); const [recordRefresh, setRecordRefresh] = useState(0);
  useEffect(() => {
    setLinkError(''); setLinkNotice('');
    if (linkedFact === null) { if (linkedRevision !== null) setLinkError('This source-revision link is missing its actual journal. Choose the saved source explicitly below.'); return; }
    setEditor(''); setRecord(null); setTarget('');
    if (!uuid.test(linkedFact) || params.getAll('pt_journal_fact').length !== 1 || linkedRevision !== null && (!/^[1-9]\d*$/.test(linkedRevision) || !Number.isSafeInteger(Number(linkedRevision)) || params.getAll('pt_journal_fact_revision').length !== 1)) { setLinkError('This saved-journal link is invalid. Choose the actual journal below; no other source has been substituted.'); return; }
    setTarget(linkedFact); setRecordRefresh(value => value + 1);
  }, [linkedFact, linkedRevision, params.toString()]);
  const listKey = `${farm.id}/${farm.revision}/${offset}/${refresh}`; const current = result.key === listKey ? result : null;
  useEffect(() => {
    const controller = new AbortController(); let active = true; setContextState({ key: contextKey });
    async function loadContext(): Promise<PreparationContext> {
      for (const [name, id] of [['pt_journal_reissue', reissueId], ['pt_journal_request', requestId]] as const) if (id !== null && (!uuid.test(id) || params.getAll(name).length !== 1)) throw new Error('This request or correction link is invalid. No unlinked preview has been substituted. Open the original request or report and try its link again.');
      let report: RecordItem | undefined; let request: RecordItem | undefined;
      if (reissueId !== null) {
        report = await (await api.downloadResponse(`/reports/${reissueId}?view=review`, { signal: controller.signal })).json() as RecordItem;
        if (typeof report.id !== 'string' || report.id.toLowerCase() !== reissueId.toLowerCase() || report.kind !== 'reports' || report.workspace_id !== farm.workspace_id || report.data.farm_id !== farm.id || report.data.pack_id !== packId || report.data.status !== 'issued' || !Number.isInteger(report.revision) || report.revision < 1 || !Number.isInteger(report.data.reporting_year) || report.data.reporting_year < 2000 || report.data.reporting_year > 2200 || !/^[a-f0-9]{64}$/i.test(report.data.checksum) || report.data.review?.snapshot_checksum !== report.data.checksum) throw new Error('The linked original is not an issued Portuguese journal from this farm. No other report will be corrected.');
        if (requestId !== null && String(report.data.request_id).toLowerCase() !== requestId.toLowerCase()) throw new Error('This request does not match the original report’s actual request link. Open the correction from the original report; a request will not be replaced.');
      }
      const actualRequestId = report ? report.data.request_id : requestId;
      if (actualRequestId !== null && actualRequestId !== undefined) {
        if (typeof actualRequestId !== 'string' || !uuid.test(actualRequestId)) throw new Error('The linked request reference is invalid. It has not been replaced.');
        request = await (await api.downloadResponse(`/requests/${actualRequestId}`, { signal: controller.signal })).json() as RecordItem;
        if (typeof request.id !== 'string' || request.id.toLowerCase() !== actualRequestId.toLowerCase() || request.kind !== 'requests' || request.workspace_id !== farm.workspace_id || request.data.farm_id !== farm.id || request.data.country !== 'PT' || request.data.pack_id !== packId || !Number.isInteger(request.revision) || request.revision < 1 || !Number.isInteger(request.data.reporting_year) || request.data.reporting_year < 2000 || request.data.reporting_year > 2200 || report && request.data.reporting_year !== report.data.reporting_year) throw new Error('The linked request’s farm, Portuguese pack or year no longer matches this preparation. Check the actual request instead of using a different one.');
      }
      return { report, request };
    }
    void loadContext().then(value => { if (active) setContextState({ key: contextKey, value }); }).catch(reason => { if (active && !controller.signal.aborted) setContextState({ key: contextKey, error: errorMessage(reason) }); });
    return () => { active = false; controller.abort(); };
  }, [contextKey, reissueId, requestId]);
  useEffect(() => { const controller = new AbortController(); let active = true; setSchema(null); setSchemaError(''); api.downloadResponse(`/packs/${packId}`, { signal: controller.signal }).then(response => response.json() as Promise<ManualPack>).then(pack => { const value = checkedPack(pack); if (active) setSchema(value); }).catch(reason => { if (active && !controller.signal.aborted) setSchemaError(errorMessage(reason)); }); return () => { active = false; controller.abort(); }; }, [schemaRefresh]);
  useEffect(() => { const controller = new AbortController(); let active = true; api.downloadResponse(`/facts?${new URLSearchParams({ farm_id: farm.id, fact_key: factKey, limit: '5', offset: String(offset) })}`, { signal: controller.signal }).then(response => response.json() as Promise<Page<Journal>>).then(page => { if (!Array.isArray(page.items)) throw new Error('The journal list is incomplete.'); page.items.forEach(item => checkedJournal(item, farm)); if (active) setResult({ key: listKey, page }); }).catch(reason => { if (active && !controller.signal.aborted) setResult({ key: listKey, error: errorMessage(reason) }); }); return () => { active = false; controller.abort(); }; }, [listKey]);
  useEffect(() => { if (!target) { setRecord(null); setRecordLoading(false); return; } const controller = new AbortController(); let active = true; setRecord(null); setRecordError(''); setRecordLoading(true); readJournal(target, farm, controller.signal).then(checked => { if (active) { setRecord(checked); setLinkNotice(target === linkedFact && linkedRevision !== null && Number(linkedRevision) !== checked.revision ? 'This journal has a different current revision from the linked report source. The report retains its original selected text; the current journal below has not replaced that snapshot.' : ''); } }).catch(reason => { if (active && !controller.signal.aborted) setRecordError(errorMessage(reason)); }).finally(() => { if (active) setRecordLoading(false); }); return () => { active = false; controller.abort(); }; }, [target, recordRefresh, linkedFact, linkedRevision]);
  function saved(value: Journal) { setRecord(value); setTarget(value.id); setEditor(''); setRefresh(count => count + 1); setOffset(0); setRecordRefresh(count => count + 1); }
  const [rowsOffset, setRowsOffset] = useState(0);
  return <section id="portuguese-journal" className="paper-section"><h2>Portuguese surface-treatment journal</h2><p>Copy the DGAV model’s literal columns. Partial drafts can be kept without inventing a date or a work entry. Check the saved journal separately, then choose actual dated rows for a manual report preview.</p><Notice>Manual preparation only. No product-use authorisation, legal applicability, official upload, filing or acceptance is established here.</Notice>{!canReview && <Notice>You can read these saved journals. A farm owner or delegated reviewer must save or confirm changes.</Notice>}{schemaError ? <Notice kind="error">{schemaError}<Button variant="secondary" onClick={() => setSchemaRefresh(value => value + 1)}>Retry Portuguese form definition</Button></Notice> : !schema ? <p role="status">Opening the Portuguese source columns…</p> : <><p>{schema.notice}</p><SourceDetails schema={schema} />{canReview && <Button variant="secondary" onClick={() => { setEditor('new'); setTarget(''); setRecord(null); }}>Start or reopen a private journal draft</Button>}{editor === 'new' && canReview && <JournalEditor key="new" farm={farm} schema={schema} correction={false} scope={scope} onSaved={saved} onClose={() => setEditor('')} />}
      {contextRequested && (contextError ? <Notice kind="error">{contextError}<Button variant="secondary" onClick={() => setContextRefresh(value => value + 1)}>Retry linked request or original report</Button></Notice> : !preparation ? <p role="status">Checking the actual request or original report…</p> : <section className="card"><h3>{preparation.report ? 'Prepare a correction to the retained report' : 'Prepare the actual linked request'}</h3>{preparation.report && <><p>{String(preparation.report.data.title || 'Portuguese journal report')} · original app year {preparation.report.data.reporting_year}</p><p><Link to={`/app/reports/${preparation.report.id}`}>Read the unchanged original report and its retained rows</Link></p><p>Choose a current checked journal below, then explicitly choose replacement rows and original files. A new draft will correct this report; the original approval and its earlier rows remain unchanged.</p><details><summary>Saved version details</summary><p>Original report {preparation.report.id} · revision {preparation.report.revision}</p><p style={{ overflowWrap: 'anywhere' }}>Retained checksum: {String(preparation.report.data.checksum)}</p></details></>}{preparation.request ? <><p>Actual request: <Link to={`/app/paperwork/${preparation.request.id}`}>{String(preparation.request.data.title || 'Linked request')}</Link> · year {preparation.request.data.reporting_year}</p>{preparation.request.data.deadline && <p>Date recorded on the request: {String(preparation.request.data.deadline)}</p>}<p>This exact request link is retained. Check its current requirements; no other letter will be substituted.</p></> : <p>No letter is linked. A correction keeps that original unlinked context.</p>}</section>)}
      <h3>Saved journals for this farm</h3>{current?.error ? <Notice kind="error">{current.error}<Button variant="secondary" onClick={() => setRefresh(value => value + 1)}>Retry saved journals</Button></Notice> : !current?.page ? <p role="status">Opening saved journals…</p> : <>{current.page.items.length ? <ul className="record-list">{current.page.items.map(item => <li key={item.id}><div><strong>{item.data.label}</strong><p>{item.data.review_status === 'confirmed' ? 'Checked by a person' : item.data.review_status === 'rejected' ? 'Rejected or replaced; history retained' : 'Proposed; needs separate review'} · {item.data.value.entries.length} saved rows · saved {new Date(item.updated_at).toLocaleString()}</p><Button variant="secondary" onClick={() => { setTarget(item.id); setEditor(''); setRowsOffset(0); setLinkError(''); setRecordRefresh(value => value + 1); }}>Open this saved journal</Button></div></li>)}</ul> : <p>No journal is saved on this page. This is not a statement that treatment records are unnecessary.</p>}<Pages offset={offset} total={current.page.total} size={5} setOffset={setOffset} label="Saved journal pages" /></>}
      {linkError && <Notice kind="error">{linkError}</Notice>}{linkNotice && <Notice kind="warning">{linkNotice}</Notice>}
      {recordLoading && <p role="status">Opening the current saved journal…</p>}{recordError && <Notice kind="error">{recordError}<Button variant="secondary" onClick={() => setRecordRefresh(value => value + 1)}>Retry this saved journal</Button></Notice>}
      {record && <section className="paper-section"><h3>Read back the saved Portuguese journal</h3><h4>{schema.identity.label}</h4><RawValue value={record.data.value.identity_text} /><h4>{schema.observations.label} — whole journal</h4><RawValue value={record.data.value.observations_text} /><RowTable value={record.data.value} schema={schema} offset={rowsOffset} setOffset={setRowsOffset} /><DocumentSources farm={farm} choices={record.data.sources || []} /><details><summary>Saved version details</summary><p>Source journal {record.id} · revision {record.revision}</p>{record.data.supersedes_id && <p>Proposed correction of {record.data.supersedes_id}</p>}{record.data.superseded_by && <p>Replaced by {record.data.superseded_by}; this original remains in history.</p>}</details><Button variant="secondary" onClick={() => setRecordRefresh(value => value + 1)}>Reload this saved journal</Button>
        {canReview && record.data.review_status === 'proposed' && <><Button variant="secondary" onClick={() => setEditor('edit')}>Edit this proposed journal</Button><JournalReview key={`${record.id}:${record.revision}`} farm={farm} record={record} onSaved={saved} /></>}{canReview && record.data.review_status === 'confirmed' && !record.data.superseded_by && <><Button variant="secondary" onClick={() => setEditor('correct')}>Prepare a correction to this checked journal</Button>{preparation && !linkError ? <PrepareJournal key={`${record.id}:${record.revision}`} farm={farm} record={record} schema={schema} scope={scope} context={preparation} /> : <p>Resolve the linked source, request or report above before preparing a preview. No unlinked report will be substituted.</p>}</>}{canReview && (editor === 'edit' || editor === 'correct') && <JournalEditor key={`${record.id}:${editor}`} farm={farm} schema={schema} record={record} correction={editor === 'correct'} scope={scope} onSaved={saved} onClose={() => setEditor('')} />}
      </section>}
      <Button variant="secondary" onClick={() => { setRefresh(value => value + 1); setRecordRefresh(value => value + 1); setContextRefresh(value => value + 1); }}>Refresh Portuguese journals</Button>
    </>}</section>;
}

export function PortugueseJournal({ farm }: { farm: RecordItem }) {
  const { session, loading } = useSession();
  const [params] = useSearchParams();
  if (loading || !session || farm.data.country !== 'PT' || farm.workspace_id !== session.workspace.id || Array.isArray(session.workspace.farm_ids) && !session.workspace.farm_ids.includes(farm.id)) return null;
  const binding = JSON.stringify([session.user.id, session.workspace.id, session.workspace.role, session.workspace.permissions, session.workspace.farm_ids, farm.id, farm.revision, params.getAll('pt_journal_fact'), params.getAll('pt_journal_fact_revision'), params.getAll('pt_journal_reissue'), params.getAll('pt_journal_request')]);
  return <FarmJournal key={binding} farm={farm} scope={`${session.user.id}/${session.workspace.id}`} canReview={session.workspace.role === 'owner' || session.workspace.role === 'adviser' && session.workspace.permissions?.includes('review') === true} />;
}
